head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getAllPopupWindowList]<br/>현재 열려 있는 모든 팝업의 Window 객체를 배열로 반환합니다.",
    "validation" : [
        "useMain(선택) 파라미터로 iframePopup/browserPopup 에서 $p.main() 결과 반환 여부를 설정할 수 있어야 합니다.",
        "useMain(선택) 파라미터를 true 로 설정하면 반환된 Window 의 $p.main() 결과를 반환해야 합니다.",
        "useMain(선택) 파라미터를 false 로 설정하면 Window 객체를 그대로 반환해야 합니다.",
        "useMain(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "열려 있는 모든 팝업의 Window 객체 배열을 반환해야 합니다.",
        "열려 있는 팝업이 없으면 빈 배열([])을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var popupId = par_popupId.getValue();

    var options = {
        id: popupId,
        type: "iframePopup",
        width: "400px",
        height: "250px",
        top: "100px",
        left: "100px",
        popupName: popupId,
        modal: false
    };

    $p.openPopup("/sample/common_link/util_createPopup_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (id: " + popupId + ", type: iframePopup)");
}



scwin.btn_getAllPopupWindowList_onclick = function () {
    var useMain = par_useMain.getValue();

    var popWinList;
    if (useMain === "omit") {
        popWinList = $p.getAllPopupWindowList();
    } else {
        popWinList = $p.getAllPopupWindowList(useMain === "true");
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getAllPopupWindowList(" + (useMain === "omit" ? "" : useMain) + ") 배열 길이 : " + popWinList.length);

    if (popWinList.length > 0) {
        for (var i = 0; i < popWinList.length; i++) {
            var win = popWinList[i];
            var constructorName = win ? win.constructor.name : "null";
            var hasDocument = (win && win.document !== undefined);
            wf_body_bottom.getObj("scwin").setReturnValue("  [" + i + "] constructor: " + constructorName + ", document: " + hasDocument);
        }
        // wf_body_bottom.getObj("scwin").setReturnValue("※ useMain=false → constructor:Window, document:true / useMain=true → constructor:Object, document:false");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열려 있는 팝업 없음 (빈 배열)");
    }
}



scwin.btn_closeAll_onclick = function () {
    var popList = $p.getAllPopupList();
    for (var i = popList.length - 1; i >= 0; i--) {
        $p.closePopup(popList[i].id);
    }

    setTimeout(function () {
        var afterList = $p.getAllPopupWindowList();
        wf_body_bottom.getObj("scwin").setReturnValue("전체 닫기 완료, 남은 팝업 Window : " + afterList.length + "개");
    }, 500);
}
